//! Emitted-only typed event streams for the Rust HTTP adapter. The static
//! runtime gains nothing: every event union, completion type and pull iterator
//! below is generated into the consumer package only when the plan carries a
//! source-selected discriminated SSE stream operation, and each operation's
//! lenient envelope reader and request path are appended to its own emitted
//! operation module.
//!
//! Iterators reuse the emitted operation's request path for transport,
//! validation and headers, and take the item stream over a lenient envelope
//! reader (`JsonValue` passes through unvalidated) so the compiled per-kind
//! decode, sentinel and completion semantics apply here. Recognized event
//! kinds decode through the operation's existing stream item codec into its
//! declared model type; undeclared event kinds surface through the typed
//! unknown alternative without failing the stream; invalid payloads of
//! recognized kinds remain decoding errors.

use super::*;
use crate::rust_models::prose;

use super::super::stream_events::StreamEventsEntry;

/// Everything `package` needs to emit typed event stream support.
pub(super) struct Emission {
    /// The generated `rust/src/stream_events.rs` module content.
    pub(super) module: String,
    /// Client-impl methods appended to the emitted root by `root`.
    pub(super) methods: String,
}

/// Compile the typed event stream emission for one plan, or `None` when the
/// plan has no emittable operation (the package then gains nothing at all).
pub(super) fn emission(plan: &HttpPlan) -> Option<Emission> {
    let entries = plan.stream_events();
    if entries.is_empty() {
        return None;
    }
    let mut module = String::from(
        "//! Code generated by suspect. DO NOT EDIT.\n//!\n//! Generated typed event streams for the source-selected discriminated SSE\n//! operations of this package. Every iterator is a concrete struct with a\n//! pull-based `next`: the request starts only while the returned future is\n//! first polled, and dropping the iterator cancels the response body and\n//! never fires another read. The declared sentinel, when compiled, completes\n//! the stream before any payload decoding and preserves the final usage frame\n//! as the documented completion metadata.\n\n/// Why one typed event stream completed.\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum CompletionReason {\n    /// The declared terminal token completed the stream before any payload\n    /// decoding.\n    Sentinel,\n    /// The response body ended.\n    Eof,\n}\n",
    );
    let mut methods = String::new();
    let mut emitted = 0usize;
    for op in plan.operations() {
        let Some(entry) = entries.iter().find(|entry| entry.module == op.module_name) else {
            continue;
        };
        module.push_str(&operation_module(plan, op, entry));
        methods.push_str(&client_method(op, entry));
        emitted += 1;
    }
    if emitted == 0 {
        return None;
    }
    Some(Emission { module, methods })
}

/// A per-entry collision-safe variant name allocation.
fn variant_names(entry: &StreamEventsEntry) -> Vec<String> {
    let mut used = std::collections::BTreeSet::from(["Unknown".to_owned()]);
    entry
        .events
        .iter()
        .map(|kind| super::super::allocate(&crate::rust_models::pascal(kind), &mut used))
        .collect()
}

fn operation_module(_plan: &HttpPlan, op: &PlannedOperation, entry: &StreamEventsEntry) -> String {
    let input = format!("crate::operations::{}::{}", entry.module, entry.input_type);
    let error = format!("crate::operations::{}::{}", entry.module, entry.error_type);
    let events_type = format!("{}Event", entry.stem);
    let completion_type = format!("{}Completion", entry.stem);
    let iterator_type = format!("{}Events", entry.stem);
    let fetch = format!(
        "crate::operations::{}::{}_events_stream",
        entry.module, entry.function
    );
    let constructor = format!("{}_events", entry.function);
    let model = format!("crate::models::{}", entry.item_model);
    let label = format!("{} {}", op.wire().method().as_str(), op.wire().path());
    let variants = variant_names(entry);
    let mut code = String::new();

    code.push_str(&format!(
        "\n// ---- {label} — {} typed events ----\n\n",
        prose(&entry.operation_id),
        label = prose(&label),
    ));
    code.push_str(&decode_error_source(entry));
    code.push_str(&event_type(entry, &events_type, &variants, &model));
    code.push_str(&completion_source(entry, &completion_type, &events_type));
    code.push_str(&iterator_source(
        entry,
        &iterator_type,
        &events_type,
        &completion_type,
        &fetch,
        &constructor,
        &input,
        &error,
        &variants,
    ));
    code
}

/// The lenient envelope reader and request path for one typed event stream,
/// appended to that operation's emitted module: they reach the operation's
/// descriptor and its input's concrete media selection, which stay private to
/// the module. Used only by [`crate::stream_events`].
pub(super) fn operation_helpers(
    plan: &HttpPlan,
    op: &PlannedOperation,
    entry: &StreamEventsEntry,
) -> String {
    let label = format!("{} {}", op.wire().method().as_str(), op.wire().path());
    let envelope = format!("{}_events_envelope", entry.function);
    let fetch = format!("{}_events_stream", entry.function);
    let mut code = String::new();
    code.push_str(&format!(
        "\n// ---- {label} — {} typed events ----\n\n/// Lenient envelope reader for the `{}` typed events: the framer's parsed\n/// envelope values pass through unvalidated so undeclared event kinds stay\n/// representable, while the compiled per-kind codecs decode recognized kinds\n/// in `crate::stream_events`.\nfn {envelope}(\n    value: crate::JsonValue,\n) -> std::result::Result<crate::JsonValue, crate::codecs::CodecError> {{\n    std::result::Result::Ok(value)\n}}\n",
        prose(&entry.operation_id),
        entry.function,
        label = prose(&label),
        envelope = envelope,
    ));
    code.push_str(&fetch_source(plan, op, entry, &fetch, &envelope));
    code
}

/// The copied request path of the operation function, returning the declared
/// event stream over the lenient envelope reader.
fn fetch_source(
    plan: &HttpPlan,
    op: &PlannedOperation,
    entry: &StreamEventsEntry,
    fetch: &str,
    envelope: &str,
) -> String {
    let operations = format!("crate::operations::{}", entry.module);
    let input = &entry.input_type;
    let error = &entry.error_type;
    let mut code = format!(
        "/// Issue the `{function}` request and return its declared event stream as\n/// leniently framed envelopes: the framing, byte limits and cancellation are\n/// the untyped item stream's, while the envelope passes through unvalidated so\n/// the typed decode below owns per-kind validation and undeclared kinds stay\n/// representable.\npub(crate) async fn {fetch}<T: crate::http::Transport>(\n    client: &crate::http::Client<T>,\n    input: {operations}::{input},\n) -> std::result::Result<crate::http::ItemStream<crate::JsonValue>, {operations}::{error}>\nwhere\n    T::Body: 'static,\n{{\n    use {operations}::OPERATION;\n    let limits = client.limits(&OPERATION)?;\n    let {mutable}parameters = std::vec::Vec::new();\n",
        function = entry.function,
        fetch = fetch,
        operations = operations,
        input = input,
        error = error,
        mutable = if op.parameters.is_empty() { "" } else { "mut " },
    );
    if op.parameters.is_empty() && op.body.is_none() {
        code.push_str("    let _ = &input;\n");
    }
    for (i, p) in op.parameters.iter().enumerate() {
        if !p.wire.required() {
            code.push_str(&format!(
                "    if let std::option::Option::Some(value) = &input.{} {{\n",
                p.name
            ));
        }
        code.push_str(&format!(
            "    parameters.push(crate::http::ParameterValue {{ parameter: OPERATION.parameters[{i}], value: crate::codecs::{}Codec::encode_value({}).map_err(|e| crate::http::request_codec_error(OPERATION.source, {}, e))? }});\n",
            p.model,
            if p.wire.required() {
                format!("&input.{}", p.name)
            } else {
                "value".into()
            },
            descriptors::source(p.wire.source().use_site().source()),
        ));
        if !p.wire.required() {
            code.push_str("    }\n");
        }
    }
    if let Some(body) = &op.body {
        let value = if body.wire.required() {
            "&input.body".to_owned()
        } else {
            "value".to_owned()
        };
        code.push_str(if body.wire.required() {
            "    let body = {\n"
        } else {
            "    let body = if let std::option::Option::Some(value) = &input.body {\n"
        });
        if body.media.len() > 1 {
            code.push_str(&format!(
                "        let (index, bytes, content_type) = match {value} {{\n"
            ));
            for (i, m) in body.media.iter().enumerate() {
                code.push_str(&format!(
                    "            {}::{}(value) => {{ let content_type = input.content_type.as_deref().unwrap_or({:?}).to_owned(); let (bytes, content_type) = {}; ({i}, bytes, content_type) }},\n",
                    body.type_name,
                    m.variant,
                    m.wire.media_type().declared(),
                    bodies::encode_media(plan, m, "value"),
                ));
            }
            code.push_str("        };\n");
        } else {
            let m = &body.media[0];
            code.push_str(&format!(
                "        let index = 0; let content_type = input.content_type.as_deref().unwrap_or({:?}).to_owned();\n        let (bytes, content_type) = {};\n",
                m.wire.media_type().declared(),
                bodies::encode_media(plan, m, &value),
            ));
        }
        code.push_str("        std::option::Option::Some(crate::http::PreparedBody::new(&OPERATION, index, content_type, bytes)?)\n");
        code.push_str(if body.wire.required() {
            "    };\n"
        } else {
            "    } else { std::option::Option::None };\n"
        });
    } else {
        code.push_str("    let body = std::option::Option::None;\n");
    }
    let headers = entry
        .headers_type
        .as_ref()
        .map(|name| {
            format!(
                "{}::from_headers(&exchange.headers).map_err(|e| exchange.header_error({}, e))?",
                name,
                descriptors::source(&entry.headers_source)
            )
        })
        .unwrap_or_else(|| "()".into());
    code.push_str(&format!(
        "    let _ = limits;\n    let exchange = client.open(&OPERATION, &parameters, body).await?;\n    let selected = match exchange.selection() {{\n        std::result::Result::Ok(value) => value,\n        std::result::Result::Err(_) => {{\n            let raw = exchange.read().await?;\n            let failure = raw.selection(&OPERATION).expect_err(\"unmatched response\");\n            return std::result::Result::Err(failure.into());\n        }}\n    }};\n    if selected.response == {ri} && selected.media == std::option::Option::Some({mi}) {{\n        let typed_headers = {headers};\n        let response = exchange.into_item_response({envelope}, crate::http::Framing::ServerSentEvents, {item_source}, {max_item}, {media:?}, typed_headers, OPERATION.responses[{ri}].links);\n        return std::result::Result::Ok(response.data);\n    }}\n    let raw = exchange.read().await?;\n    let selected = raw.selection(&OPERATION)?;\n    match (selected.response, selected.media, selected.forbidden) {{\n        _ => std::result::Result::Err(raw.unexpected_error(OPERATION.source, OPERATION.source).into()),\n    }}\n}}\n",
        ri = entry.response_index,
        mi = entry.media_index,
        headers = headers,
        envelope = envelope,
        item_source = descriptors::source(&entry.item_source),
        max_item = entry.max_item_bytes,
        media = entry.media_type,
    ));
    code
}

/// Brand an invalid payload of a recognized kind exactly like the untyped item
/// stream's per-item decode: codec resource failures stay resource limits and
/// everything else is a response-decoding failure.
fn decode_error_source(entry: &StreamEventsEntry) -> String {
    let work = "native conversion work limit exceeded";
    let depth = "native conversion depth limit exceeded";
    let message = "stream event failed its source codec";
    let name = format!("{}_events_decode_error", entry.function);
    format!(
        "/// An invalid payload of a recognized event kind, branded exactly like the\n/// untyped item stream's per-item decode: codec resource failures stay\n/// resource limits and everything else is a response-decoding failure.\nfn {name}(cause: crate::codecs::CodecError) -> crate::http::SdkError {{\n    let limited = matches!(&cause, crate::codecs::CodecError::EvaluationFailure(_))\n        || matches!(&cause, crate::codecs::CodecError::Json(json) if json.kind == crate::JsonErrorKind::ResourceLimit)\n        || matches!(&cause, crate::codecs::CodecError::Conversion(finding) if matches!(\n            finding.message.as_str(),\n            {work:?} | {depth:?}\n        ));\n    let mut failure = crate::http::validation_error(\n        crate::operations::{module}::OPERATION.source,\n        {item_source},\n        {message:?},\n    );\n    failure.kind = if limited {{\n        crate::http::SdkErrorKind::ResourceLimit\n    }} else {{\n        crate::http::SdkErrorKind::ResponseDecoding\n    }};\n    failure.cause = std::option::Option::Some(std::boxed::Box::new(cause));\n    failure\n}}\n",
        name = name,
        module = entry.module,
        item_source = descriptors::source(&entry.item_source),
        work = work,
        depth = depth,
        message = message,
    )
}

fn event_type(
    entry: &StreamEventsEntry,
    events_type: &str,
    variants: &[String],
    model: &str,
) -> String {
    let mut members = String::new();
    if let Some(id) = &entry.id_metadata {
        members.push_str(&format!(
            "        /// The declared id envelope field, decoded with its declared type.\n        id: std::option::Option<{}>,\n",
            id.type_
        ));
    }
    if let Some(retry) = &entry.retry_metadata {
        members.push_str(&format!(
            "        /// The declared reconnection hint envelope field, decoded with its declared type.\n        retry: std::option::Option<{}>,\n",
            retry.type_
        ));
    }
    let mut code = format!(
        "/// One typed event of the `{function}` stream (`{operation_id}`). Declared\n/// kinds decode the framed envelope through the operation's stream item codec\n/// into its declared model type; an event kind the source never declared\n/// surfaces through the typed unknown alternative without failing the stream;\n/// invalid payloads of recognized kinds remain decoding errors.\n#[derive(Debug, Clone)]\npub enum {events_type} {{\n",
        function = entry.function,
        operation_id = prose(&entry.operation_id),
        events_type = events_type,
    );
    for (kind, variant) in entry.events.iter().zip(variants) {
        code.push_str(&format!(
            "    /// A declared `{kind}` event: the framed envelope decoded to its declared model type.\n    {variant} {{\n        /// The decoded envelope model.\n        data: {model},\n{members}    }},\n",
            kind = kind,
            variant = variant,
            model = model,
            members = members,
        ));
    }
    code.push_str("    /// An event kind the source never declared: the raw frame data stays\n    /// representable without failing the stream.\n    Unknown {\n        /// The undeclared event name from the framed envelope.\n        event: std::string::String,\n        /// The raw frame data.\n        data: std::string::String,\n    },\n}\n");
    code
}

fn completion_source(
    entry: &StreamEventsEntry,
    completion_type: &str,
    events_type: &str,
) -> String {
    format!(
        "/// Terminal metadata of one completed `{function}` typed event stream: why\n/// it completed and the preserved final usage frame. `next` exposes it through\n/// `completion` once the stream ended; loops discard it.\npub struct {completion_type} {{\n    /// `Sentinel` when the declared terminal token completed the stream before\n    /// any payload decoding, `Eof` when the response body ended.\n    pub reason: crate::stream_events::CompletionReason,\n    /// The last data frame before the sentinel or end of body, decoded like\n    /// an ordinary event and preserved as terminal instead of being yielded;\n    /// `None` when no frame preceded completion or the compiled policy\n    /// preserves nothing.\n    pub usage: std::option::Option<{events_type}>,\n}}\n",
        function = entry.function,
        completion_type = completion_type,
        events_type = events_type,
    )
}

#[allow(clippy::too_many_arguments)]
fn iterator_source(
    entry: &StreamEventsEntry,
    iterator_type: &str,
    events_type: &str,
    completion_type: &str,
    fetch: &str,
    constructor: &str,
    input: &str,
    error: &str,
    variants: &[String],
) -> String {
    let sentinel = match &entry.sentinel {
        Some(token) => format!(
            "            // The declared {token} sentinel completes the stream before any payload\n            // decoding.\n            if data == {token:?} {{\n                stream.close();\n                self.terminal = std::option::Option::Some({completion_type} {{\n                    reason: crate::stream_events::CompletionReason::Sentinel,\n                    usage: self.held.clone(),\n                }});\n                return std::result::Result::Ok(std::option::Option::None);\n            }}\n",
            token = token,
            completion_type = completion_type,
        ),
        None => String::new(),
    };
    // Different declared kinds share one item codec and one metadata set; the
    // variant is selected after the shared decode.
    let mut known_arms = String::new();
    for (kind, variant) in entry.events.iter().zip(variants) {
        known_arms.push_str(&format!(
            "                    {kind:?} => {events_type}::{variant} {{ data: item, {metadata} }},\n",
            kind = kind,
            events_type = events_type,
            variant = variant,
            metadata = metadata_values(entry),
        ));
    }
    let known_kinds = entry
        .events
        .iter()
        .map(|kind| format!("{kind:?}"))
        .collect::<Vec<_>>()
        .join(" | ");
    let metadata_binds = metadata_binds(entry);
    let sentinel_doc = sentinel_doc(entry);
    let decode_error = format!("{}_events_decode_error", entry.function);
    let hold = if entry.keep_final_usage {
        "            match self.held.take() {\n                std::option::Option::Some(previous) => {\n                    self.held = std::option::Option::Some(typed);\n                    return std::result::Result::Ok(std::option::Option::Some(previous));\n                }\n                std::option::Option::None => {\n                    self.held = std::option::Option::Some(typed);\n                }\n            }\n"
    } else {
        "            return std::result::Result::Ok(std::option::Option::Some(typed));\n"
    };
    format!(
        "/// Lazily yields the typed events of `{function}` over the existing stream\n/// item iteration: the framing, byte limits and cancellation are the untyped\n/// item stream's. {sentinel_doc}Iteration is pull-driven: dropping the iterator cancels the\n/// response body and issues no further reads. The direct `{function}` function\n/// and its untyped item stream are unchanged.\npub struct {iterator_type}<'a, T> {{\n    client: &'a crate::http::Client<T>,\n    input: {input},\n    stream: std::option::Option<crate::http::ItemStream<crate::JsonValue>>,\n    held: std::option::Option<{events_type}>,\n    terminal: std::option::Option<{completion_type}>,\n    failed: bool,\n}}\n\nimpl<'a, T: crate::http::Transport> {iterator_type}<'a, T> {{\n    /// The next typed event, or `None` only after the stream completed. The\n    /// request starts when the returned future is first polled, and failures\n    /// surface as the operation's own error type.\n    pub async fn next(\n        &mut self,\n    ) -> std::result::Result<\n        std::option::Option<{events_type}>,\n        {error},\n    >\n    where\n        T::Body: 'static,\n    {{\n        if self.failed || self.terminal.is_some() {{\n            return std::result::Result::Ok(std::option::Option::None);\n        }}\n        if self.stream.is_none() {{\n            let stream = {fetch}(self.client, self.input.clone()).await?;\n            self.stream = std::option::Option::Some(stream);\n        }}\n        let stream = self.stream.as_mut().expect(\"typed event stream started\");\n        loop {{\n            let std::option::Option::Some(frame) = stream.next().await else {{\n                self.terminal = std::option::Option::Some({completion_type} {{\n                    reason: crate::stream_events::CompletionReason::Eof,\n                    usage: self.held.clone(),\n                }});\n                return std::result::Result::Ok(std::option::Option::None);\n            }};\n            let envelope = match frame {{\n                std::result::Result::Ok(value) => value,\n                std::result::Result::Err(failure) => {{\n                    self.failed = true;\n                    return std::result::Result::Err({error}::Sdk(\n                        std::boxed::Box::new(failure),\n                    ));\n                }}\n            }};\n            let (kind, data) = match &envelope {{\n                crate::Nullable::Value(crate::JsonNonNullValue::Object(fields)) => {{\n                    let kind = match fields.get(\"event\") {{\n                        std::option::Option::Some(crate::Nullable::Value(\n                            crate::JsonNonNullValue::String(name),\n                        )) if !name.is_empty() => name.clone(),\n                        _ => std::string::String::from(\"message\"),\n                    }};\n                    let data = match fields.get(\"data\") {{\n                        std::option::Option::Some(crate::Nullable::Value(\n                            crate::JsonNonNullValue::String(text),\n                        )) => text.clone(),\n                        _ => std::string::String::new(),\n                    }};\n                    (kind, data)\n                }}\n                _ => (\n                    std::string::String::from(\"message\"),\n                    std::string::String::new(),\n                ),\n            }};\n{sentinel}            let typed = match kind.as_str() {{\n                {known_kinds} => {{\n                    let item = match crate::codecs::{item_model}Codec::decode_value(envelope.clone()) {{\n                        std::result::Result::Ok(item) => item,\n                        std::result::Result::Err(cause) => {{\n                            stream.close();\n                            return std::result::Result::Err({error}::Sdk(\n                                std::boxed::Box::new({decode_error}(cause)),\n                            ));\n                        }}\n                    }};\n{metadata_binds}                    match kind.as_str() {{\n{known_arms}                        _ => unreachable!(\"declared kind checked\"),\n                    }}\n                }}\n                _ => {events_type}::Unknown {{\n                    event: kind.clone(),\n                    data,\n                }},\n            }};\n{hold}        }}\n    }}\n\n    /// The documented terminal metadata once the stream completed, or `None`\n    /// before completion and after a failure.\n    pub fn completion(&self) -> std::option::Option<&{completion_type}> {{\n        self.terminal.as_ref()\n    }}\n}}\n\n/// Start a typed event stream over `input`; the request starts on the first\n/// `next`.\n#[must_use]\npub fn {constructor}<'a, T: crate::http::Transport>(\n    client: &'a crate::http::Client<T>,\n    input: {input},\n) -> {iterator_type}<'a, T> {{\n    {iterator_type} {{\n        client,\n        input,\n        stream: std::option::Option::None,\n        held: std::option::Option::None,\n        terminal: std::option::Option::None,\n        failed: false,\n    }}\n}}\n",
        function = entry.function,
        sentinel_doc = sentinel_doc,
        iterator_type = iterator_type,
        input = input,
        events_type = events_type,
        completion_type = completion_type,
        error = error,
        fetch = fetch,
        sentinel = sentinel,
        known_kinds = known_kinds,
        item_model = entry.item_model,
        decode_error = decode_error,
        metadata_binds = metadata_binds,
        known_arms = known_arms,
        hold = hold,
        constructor = constructor,
    )
}

fn sentinel_doc(entry: &StreamEventsEntry) -> String {
    match &entry.sentinel {
        Some(token) => format!(
            "The declared {token} sentinel completes the stream before any payload\n/// decoding, preserving the final usage frame as the completion's terminal\n/// metadata and issuing no further reads."
        ),
        None => String::new(),
    }
}

fn metadata_binds(entry: &StreamEventsEntry) -> String {
    let mut binds = String::new();
    if let Some(id) = &entry.id_metadata {
        let binding = format!("event_{}", id.field);
        binds.push_str(&format!(
            "                    let {binding} = {};\n",
            id.conversion
        ));
    }
    if let Some(retry) = &entry.retry_metadata {
        let binding = format!("event_{}", retry.field);
        binds.push_str(&format!(
            "                    let {binding} = {};\n",
            retry.conversion
        ));
    }
    binds
}

fn metadata_values(entry: &StreamEventsEntry) -> String {
    let mut values = Vec::new();
    if let Some(id) = &entry.id_metadata {
        values.push(format!("id: event_{}", id.field));
    }
    if let Some(retry) = &entry.retry_metadata {
        values.push(format!("retry: event_{}", retry.field));
    }
    if values.is_empty() {
        String::new()
    } else {
        format!("{}, ", values.join(", "))
    }
}

fn client_method(op: &PlannedOperation, entry: &StreamEventsEntry) -> String {
    format!(
        "    /// Lazily iterate the typed events of {}. See\n    /// [`stream_events::{}Events`].\n    #[must_use]\n    pub fn {}_events(\n        &self,\n        input: operations::{}::{},\n    ) -> stream_events::{}Events<'_, T> {{\n        stream_events::{}_events(self, input)\n    }}\n",
        prose(&format!(
            "{} {}",
            op.wire().method().as_str(),
            op.wire().path()
        )),
        entry.stem,
        entry.function,
        entry.module,
        entry.input_type,
        entry.stem,
        entry.function,
    )
}
